[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$Root)
$ErrorActionPreference='Stop'
$runtime=Join-Path $Root 'runtime';$exe=Join-Path $runtime 'DayScene.exe';$output=Join-Path $Root 'shader-cost-evidence'
if(!(Test-Path $exe)){throw "Missing $exe"};if(Test-Path $output){throw "Use a fresh output: $output"};[void][IO.Directory]::CreateDirectory($output)
function Q([string[]]$a){(($a|ForEach-Object{'"'+$_.Replace('"','\"')+'"'})-join' ')}
function Clear-Cache{ $p=Join-Path $runtime 'Shaders\.t8shadercache';if(Test-Path $p){Remove-Item $p -Recurse -Force} }
function Run([string[]]$Arguments,[string]$dir,[int]$timeout=900){[void][IO.Directory]::CreateDirectory($dir);$sw=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process $exe -WorkingDirectory $runtime -ArgumentList (Q $Arguments) -RedirectStandardOutput (Join-Path $dir 'stdout.log') -RedirectStandardError (Join-Path $dir 'stderr.log') -PassThru;$null=$p.Handle;try{if(!$p.WaitForExit($timeout*1000)){$p.Kill();$p.WaitForExit();throw 'Timeout'};$exit=$p.ExitCode}finally{if(!$p.HasExited){$p.Kill();$p.WaitForExit()};$p.Dispose();$sw.Stop()};if($exit-ne0){throw "Exit ${exit}: $dir"};[pscustomobject]@{wallMs=$sw.Elapsed.TotalMilliseconds;arguments=$Arguments}}
$compile=@();foreach($case in @([pscustomobject]@{n='d3d12';a='d3d12';f=$null},[pscustomobject]@{n='wgsl';a='webgpu';f='wgsl'},[pscustomobject]@{n='spirv';a='webgpu';f='spirv'})){foreach($state in 'cold','warm'){if($state-eq'cold'){Clear-Cache};$dir=Join-Path $output "compile-all\$($case.n)-$state";$arguments=@('--compileShaders','--api',$case.a,'--logLevel','info');if($case.f){$arguments+=@('--shaderFlow',$case.f)};$run=Run $arguments $dir;$text=(Get-Content (Join-Path $dir 'stdout.log') -Raw)+(Get-Content (Join-Path $dir 'stderr.log') -Raw);$m=[regex]::Match($text,'\[ShaderPrecompile\] complete: (\d+) succeeded, (\d+) failed');if(!$m.Success-or[int]$m.Groups[2].Value-ne0){throw "Compile failure: $($case.n) $state"};$compile+=[pscustomobject]@{case=$case.n;state=$state;wallMs=$run.wallMs;succeeded=[int]$m.Groups[1].Value}}}
$cells=@([pscustomobject]@{n='d3d12-raster';a='d3d12';f=$null;m='raster'},[pscustomobject]@{n='d3d12-compute';a='d3d12';f=$null;m='compute'},[pscustomobject]@{n='wgsl-raster';a='webgpu';f='wgsl';m='raster'},[pscustomobject]@{n='wgsl-compute';a='webgpu';f='wgsl';m='compute'},[pscustomobject]@{n='spirv-raster';a='webgpu';f='spirv';m='raster'},[pscustomobject]@{n='spirv-compute';a='webgpu';f='spirv';m='compute'})
$startup=@();foreach($cell in $cells){foreach($state in 'cold','warm'){if($state-eq'cold'){Clear-Cache};$dir=Join-Path $output "startup\$($cell.n)-$state";[void][IO.Directory]::CreateDirectory($dir);$arguments=@('--api',$cell.a,'--scene','1','--width','1920','--height','1080','--postProcessMode',$cell.m,'--culling','full','--profileCpuOnly','--profileFrames','1','--telemetry','--telemetryFrequencyFrames','0','--telemetryOutput',(Join-Path $dir 'telemetry.json'),'--logLevel','info','--logFile',(Join-Path $dir 'engine.log'));if($cell.f){$arguments+=@('--shaderFlow',$cell.f)};$run=Run $arguments $dir 300;$log=Get-Content (Join-Path $dir 'engine.log') -Raw;if($log-match'\[ERROR\s*\]|Device lost|Queue submission failed'){throw "Startup error: $($cell.n) $state"};$reports=@(Get-ChildItem $dir -Filter 'telemetry_*.json');if($reports.Count-ne1){throw 'Telemetry missing'};$t=Get-Content $reports[0].FullName -Raw|ConvertFrom-Json;$s=@($t.frames|Where-Object startup)[0];$startup+=[pscustomobject]@{cell=$cell.n;state=$state;wallMs=$run.wallMs;firstRuntimeFrameCompleteMs=$t.startupTiming.firstRuntimeFrameCompleteMs;shaderScopes=@($s.scopes|Where-Object name -Match '^(shader\.|pipeline\.)');shaderCounters=@($s.counters|Where-Object name -Match '^shader\.')}}}
$result=[pscustomobject]@{schema=1;completedUtc=[DateTime]::UtcNow.ToString('o');passed=$true;machine=$env:COMPUTERNAME;architecture=$env:PROCESSOR_ARCHITECTURE;executableSha256=(Get-FileHash $exe).Hash;compileAll=$compile;startup=$startup};$result|ConvertTo-Json -Depth 10|Set-Content (Join-Path $output 'result.json') -Encoding UTF8;Write-Output "PASS: shader costs at $output"
